/**
 * Content of the Kopffeld-Check explanation page — OBO-156, mockup page 4.
 *
 * Only translation keys and layout hints live here; every sentence is a
 * Tolgee key, so the page template is a loop over these two lists.
 */

export interface HelpStep {
  /** Position in the chain, shown as "Schritt n". */
  number: number;
  icon: string;
  titleKey: string;
  textKey: string;
}

export type HelpSourceTone = 'neutral' | 'warning' | 'success';

export interface HelpSource {
  id: string;
  icon: string;
  tone: HelpSourceTone;
  chipKey: string;
  textKey: string;
  exampleKey: string;
  fixKey: string;
  /** Where in the settings it is changed, for sources that have such a page. */
  fixPathKey: string | null;
}

const STEP_IDS = [
  { id: 'read', icon: 'mdi:file-document-outline' },
  { id: 'transform', icon: 'mdi:code-braces' },
  { id: 'lookup', icon: 'mdi:database-search' },
  { id: 'display', icon: 'mdi:eye-outline' },
] as const;

export const HELP_STEPS: readonly HelpStep[] = STEP_IDS.map(({ id, icon }, index) => ({
  number: index + 1,
  icon,
  titleKey: `header_field_check_help_step_${id}_title`,
  textKey: `header_field_check_help_step_${id}_text`,
}));

const SOURCE_IDS: readonly {
  id: string;
  icon: string;
  tone: HelpSourceTone;
  /** The source has a settings page the fix can point to. */
  settingsPath?: boolean;
}[] = [
  { id: 'trained_rule', icon: 'mdi:target', tone: 'neutral' },
  { id: 'ai', icon: 'mdi:robot-outline', tone: 'neutral', settingsPath: true },
  { id: 'edocument', icon: 'mdi:xml', tone: 'neutral' },
  { id: 'script', icon: 'mdi:code-braces', tone: 'warning' },
  { id: 'master_data', icon: 'mdi:database-outline', tone: 'success', settingsPath: true },
  { id: 'calculated', icon: 'mdi:calculator-variant-outline', tone: 'neutral' },
  { id: 'barcode', icon: 'mdi:barcode-scan', tone: 'neutral' },
];

export const HELP_SOURCES: readonly HelpSource[] = SOURCE_IDS.map(
  ({ id, icon, tone, settingsPath }) => ({
    id,
    icon,
    tone,
    chipKey: `header_field_check_help_source_${id}_chip`,
    textKey: `header_field_check_help_source_${id}_text`,
    exampleKey: `header_field_check_help_source_${id}_example`,
    fixKey: `header_field_check_help_source_${id}_fix`,
    fixPathKey: settingsPath ? `header_field_check_help_source_${id}_fix_path` : null,
  }),
);

/** Card classes per tone — semantic tokens only. */
export const HELP_SOURCE_TONE_CLASSES: Record<HelpSourceTone, string> = {
  neutral: 'border-border bg-card',
  warning: 'border-warning/40 bg-warning/5',
  success: 'border-success/40 bg-success/5',
};

/**
 * The example in the misunderstanding box: what the script left ("1001") and
 * the order number the partial lookup matched it inside. Data, not language —
 * the same in every locale.
 */
export const HELP_MISUNDERSTANDING_EXAMPLE = {
  needle: '1001',
  matchedValue: '06O051001',
} as const;
