<!--
  "Woher die Daten kommen — und wie sie entstehen" — OBO-156, mockup page 4.

  The explanation page linked from the Kopffeld-Check report. Written for
  consultants and customers: the four steps a value goes through, the seven
  sources a value can come from, and the one misunderstanding that causes
  most of the reported cases. Static content; every sentence is a Tolgee key
  listed in headerFieldCheckHelpContent.ts.
-->
<template>
  <div class="hfc-help mx-auto flex w-full max-w-6xl flex-col gap-8 px-4 py-6 text-sm text-foreground sm:px-6">
    <header class="flex flex-col gap-1">
      <div class="text-xs font-semibold tracking-wide text-primary">DocBits</div>
      <h1 class="text-2xl font-semibold leading-tight">{{ $t('header_field_check_help_title') }}</h1>
      <p class="text-muted-foreground">{{ $t('header_field_check_help_subtitle') }}</p>
    </header>

    <section class="flex flex-col gap-3">
      <h2 class="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
        {{ $t('header_field_check_help_order_heading') }}
      </h2>
      <!-- `lg:` switches the steps to a row AND turns the arrows from down to
           right; the two must stay on the same breakpoint. -->
      <ol class="flex flex-col items-stretch gap-2 lg:flex-row lg:items-center">
        <template v-for="(step, index) in steps" :key="step.number">
          <li
            data-test="hfc-help-step"
            class="flex flex-1 flex-col gap-2 self-stretch rounded-md border border-border bg-card p-4"
          >
            <div class="flex items-center gap-2 text-xs font-semibold tracking-wide text-primary">
              <Icon :icon="step.icon" class="size-4" />
              {{ $t('header_field_check_help_step_label', { number: step.number }) }}
            </div>
            <div class="text-base font-semibold">{{ $t(step.titleKey) }}</div>
            <p class="text-muted-foreground">{{ $t(step.textKey) }}</p>
          </li>
          <li
            v-if="index < steps.length - 1"
            data-test="hfc-help-step-arrow"
            aria-hidden="true"
            class="flex shrink-0 justify-center text-muted-foreground"
          >
            <Icon icon="mdi:arrow-right" class="size-5 rotate-90 lg:rotate-0" />
          </li>
        </template>
      </ol>
      <p class="text-muted-foreground">{{ $t('header_field_check_help_order_note') }}</p>
    </section>

    <section class="flex flex-col gap-3">
      <h2 class="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
        {{ $t('header_field_check_help_sources_heading') }}
      </h2>
      <div class="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
        <article
          v-for="source in sources"
          :key="source.id"
          data-test="hfc-help-source"
          :data-source="source.id"
          class="flex flex-col gap-3 rounded-md border p-4"
          :class="toneClasses[source.tone]"
        >
          <span
            data-test="hfc-help-source-chip"
            class="inline-flex w-fit items-center gap-1 rounded-full border border-border bg-background px-2 py-0.5 text-xs font-semibold"
          >
            <Icon :icon="source.icon" class="size-4" />
            {{ $t(source.chipKey) }}
          </span>
          <p>{{ $t(source.textKey) }}</p>
          <p data-test="hfc-help-source-example" class="text-muted-foreground">
            <span class="font-semibold text-foreground">{{ $t('header_field_check_help_example_label') }}</span>
            {{ $t(source.exampleKey) }}
          </p>
          <p data-test="hfc-help-source-fix" class="mt-auto border-t border-border pt-3">
            <span class="font-semibold">{{ $t('header_field_check_help_fix_label') }}</span>
            {{ $t(source.fixKey) }}
            <span
              v-if="source.fixPathKey"
              data-test="hfc-help-source-fix-path"
              class="mt-1 block text-xs text-muted-foreground"
              >{{ $t(source.fixPathKey) }}</span
            >
          </p>
        </article>
      </div>
    </section>

    <section
      data-test="hfc-help-misunderstanding"
      class="flex flex-col gap-2 rounded-md border-2 border-destructive/60 bg-destructive/5 p-4"
    >
      <h2 class="flex items-center gap-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
        <Icon icon="mdi:alert-circle-outline" class="size-4 text-destructive" />
        {{ $t('header_field_check_help_misunderstood_heading') }}
      </h2>
      <p>
        {{ $t('header_field_check_help_misunderstood_lead') }}
        <span class="font-mono font-semibold">{{ example.needle }}</span>
        {{ $t('header_field_check_help_misunderstood_fits') }}
        <span data-test="hfc-help-matched-value" class="font-mono font-semibold"
          >{{ matchedParts.before }}<mark class="hfc-help-hl">{{ example.needle }}</mark
          >{{ matchedParts.after }}</span
        >{{ $t('header_field_check_help_misunderstood_tail') }}
      </p>
    </section>

    <footer class="border-t border-border pt-3 text-xs text-muted-foreground">
      {{ $t('header_field_check_help_footer') }}
    </footer>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
import {
  HELP_MISUNDERSTANDING_EXAMPLE,
  HELP_SOURCE_TONE_CLASSES,
  HELP_SOURCES,
  HELP_STEPS,
} from './headerFieldCheckHelpContent';

export default defineComponent({
  name: 'HeaderFieldCheckHelpPage',
  components: { Icon },
  data() {
    return {
      steps: HELP_STEPS,
      sources: HELP_SOURCES,
      toneClasses: HELP_SOURCE_TONE_CLASSES,
      example: HELP_MISUNDERSTANDING_EXAMPLE,
    };
  },
  computed: {
    /** The matched value split around the needle, so the needle can be marked. */
    matchedParts(): { before: string; after: string } {
      const { needle, matchedValue } = this.example;
      const at = matchedValue.lastIndexOf(needle);
      return {
        before: matchedValue.slice(0, at),
        after: matchedValue.slice(at + needle.length),
      };
    },
  },
});
</script>

<style scoped>
.hfc-help-hl {
  background: color-mix(in srgb, var(--destructive) 25%, transparent);
  color: inherit;
  border-radius: 2px;
  padding: 0 1px;
}
</style>
